scripts.test_critical_moe.py:
import unittest
from critical_moe import reconstruct

def row(a,b,name,cat):return {'start':a,'end':b,'name':name,'category':cat,'capture_scope':''}
class CriticalMoeTests(unittest.TestCase):
 def test_routed_router_is_charged_even_while_shared_branch_runs(self):
  r=reconstruct([row(0,1,'norm','input'),row(1,7,'shared','shared_mlp_gateup'),row(1,4,'router','router'),row(4,10,'mma','trellis'),row(10,11,'post','post')])
  self.assertEqual(r['winner'],'routed')
  self.assertEqual(r['critical_category_ns']['router'],3)
  self.assertNotIn('shared_mlp_gateup',r['critical_category_ns'])
  self.assertEqual(sum(r['critical_category_ns'].values()),11)
 def test_shared_branch_can_become_critical(self):
  r=reconstruct([row(0,1,'norm','input'),row(1,12,'shared','shared_mlp_gateup'),row(1,10,'mma','trellis'),row(12,13,'post','post')])
  self.assertEqual(r['winner'],'shared')
  self.assertEqual(r['critical_category_ns']['shared_mlp_gateup'],11)
  self.assertNotIn('trellis',r['critical_category_ns'])
 def test_incomplete_dependency_order_is_rejected(self):
  with self.assertRaises(AssertionError):
   reconstruct([row(0,1,'norm','input'),row(1,12,'shared','shared_mlp_gateup'),row(1,10,'mma','trellis'),row(11,13,'post','post')])
if __name__=='__main__':unittest.main()
